package glitch

import data.glitch_lib

weak_hash_patterns := "(?i)(md5|sha1|sha-1|sha128|md4)"
weak_encryption_patterns := "(?i)(des|3des|rc4|aes-128|md5_crypt|des-cbc3-sha|rc4-md5)"
outdated_protocol_patterns := "(?i)(ssl2|ssl3|tls1|tls1\\.0|tls1\\.1)"
insecure_cipher_patterns := "(?i)(cbc|rc4|null|export)"

has_weak_algorithm(node) {
    glitch_lib.traverse(node, weak_hash_patterns)
}

has_weak_algorithm(node) {
    glitch_lib.traverse(node, weak_encryption_patterns)
}

has_weak_algorithm(node) {
    glitch_lib.traverse(node, outdated_protocol_patterns)
}

has_weak_algorithm(node) {
    glitch_lib.traverse(node, insecure_cipher_patterns)
}

has_weak_algorithm(node) {
    node.ir_type == "FunctionCall"
    some arg in node.args
    has_weak_algorithm(arg)
}

is_encryption_related(name) {
    regex.match("(?i)(algorithm|cipher|encryption|key|ssl|tls|protocol|hash|encrypt|password|salt|key_size|key_length|auth_method)", name)
}

